package com.example.crm.auth;
import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {final AuthService s; AuthController(AuthService x){s=x;} record Login(@NotBlank String username,@NotBlank String password){} record Refresh(@NotBlank String refreshToken){} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody Login r){try{return ResponseEntity.ok(s.login(r.username(),r.password()));}catch(IllegalArgumentException e){return ResponseEntity.status(401).body(Map.of("error","invalid_credentials"));}} @PostMapping("/refresh") public ResponseEntity<?> refresh(@RequestBody Refresh r){try{return ResponseEntity.ok(s.refresh(r.refreshToken()));}catch(IllegalArgumentException e){return ResponseEntity.status(401).body(Map.of("error","invalid_refresh_token"));}} @PostMapping("/logout") public ResponseEntity<Void> logout(@RequestBody Refresh r){s.logout(r.refreshToken());return ResponseEntity.noContent().build();} }
